DROP TABLE IF EXISTS `engineering_die`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `engineering_die` (
  `die_id` bigint NOT NULL AUTO_INCREMENT COMMENT '刀模实体ID',
  `die_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '刀模编号',
  `die_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '刀模名称',
  `purpose` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用途',
  `specification` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '规格参数',
  `version` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '版本',
  `quantity` int DEFAULT NULL COMMENT '数量(把)',
  `location` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '存放位置',
  `stock_in_date` date DEFAULT NULL COMMENT '入库日期',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'AVAILABLE' COMMENT 'AVAILABLE可用/MAINTENANCE维护中/STOPPED停用/REPLACED已重做/SCRAPPED报废',
  `predecessor_id` bigint DEFAULT NULL COMMENT '重做来源刀模ID',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`die_id`),
  UNIQUE KEY `uk_engineering_die_no` (`die_no`),
  KEY `idx_engineering_die_status` (`status`),
  KEY `idx_engineering_die_predecessor` (`predecessor_id`),
  CONSTRAINT `fk_engineering_die_predecessor` FOREIGN KEY (`predecessor_id`) REFERENCES `engineering_die` (`die_id`)
) ENGINE=InnoDB AUTO_INCREMENT=24269 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='工程-刀模实体';
