--
-- Table structure for table `engineering_film`
--

DROP TABLE IF EXISTS `engineering_film`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `engineering_film` (
  `film_id` bigint NOT NULL AUTO_INCREMENT COMMENT '菲林ID',
  `film_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '菲林编码',
  `film_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '菲林名称',
  `film_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '菲林类型：OVERLAY/UPPER_CIRCUIT/SPACER/LOWER_CIRCUIT/BACK_ADHESIVE',
  `product_id` bigint NOT NULL COMMENT '关联产品ID',
  `product_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '产品编码',
  `product_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '产品名称',
  `version` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'v1.0' COMMENT '版本号',
  `is_current` tinyint DEFAULT '1' COMMENT '是否当前版本：0-否,1-是',
  `parent_film_id` bigint DEFAULT NULL COMMENT '父菲林ID',
  `film_size` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '菲林尺寸',
  `film_thickness` decimal(10,3) DEFAULT NULL COMMENT '菲林厚度(mm)',
  `film_material` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '菲林材料',
  `color` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '颜色',
  `file_id` bigint DEFAULT NULL COMMENT '文件ID',
  `file_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件路径',
  `file_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件名',
  `technical_spec` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '技术规格',
  `design_notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '设计说明',
  `process_id` bigint DEFAULT NULL COMMENT '关联工序ID',
  `process_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联工序编码',
  `approve_status` tinyint NOT NULL DEFAULT '1' COMMENT '审核状态: 1草稿,2待审批,3已批准,4已驳回',
  `approver_id` bigint DEFAULT NULL COMMENT '审核人ID',
  `approver_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审核人姓名',
  `approve_time` datetime DEFAULT NULL COMMENT '审核时间',
  `approve_remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审核意见',
  `designer_id` bigint DEFAULT NULL COMMENT '设计人员ID',
  `designer_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设计人员姓名',
  `design_time` datetime DEFAULT NULL COMMENT '设计完成时间',
  `is_released` tinyint NOT NULL DEFAULT '0' COMMENT '是否下发生产：0-否,1-是',
  `release_time` datetime DEFAULT NULL COMMENT '下发生产时间',
  `release_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '下发人',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `deleted` tinyint DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`film_id`),
  UNIQUE KEY `uk_film_code_version` (`film_code`,`version`),
  KEY `idx_product_id` (`product_id`),
  KEY `idx_film_type` (`film_type`),
  KEY `idx_approve_status` (`approve_status`),
  KEY `idx_is_current` (`is_current`),
  CONSTRAINT `chk_film_type` CHECK ((`film_type` in (_utf8mb4'OVERLAY',_utf8mb4'UPPER_CIRCUIT',_utf8mb4'SPACER',_utf8mb4'LOWER_CIRCUIT',_utf8mb4'BACK_ADHESIVE')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='产品菲林表';
