--
-- Table structure for table `engineering_routing_item`
--

DROP TABLE IF EXISTS `engineering_routing_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `engineering_routing_item` (
  `detail_id` bigint NOT NULL AUTO_INCREMENT COMMENT '明细ID',
  `routing_id` bigint NOT NULL COMMENT '路线ID',
  `process_id` bigint DEFAULT NULL COMMENT '标准工序ID（可空，匹配不到时由工程后续完善）',
  `process_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工序名称（印刷等自定义工序冗余，标准工序可空走关联）',
  `major_category` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ASSEMBLY' COMMENT '大类：ASSEMBLY冲型组装/PRINT印刷',
  `process_order` int DEFAULT NULL,
  `custom_labor_hours` decimal(10,2) DEFAULT NULL COMMENT '定制人工工时',
  `custom_machine_hours` decimal(10,2) DEFAULT NULL COMMENT '定制机器工时',
  `standard_wage` decimal(10,2) DEFAULT NULL COMMENT '标准工价(元/工时,059人工成本核算)',
  `custom_process_params` json DEFAULT NULL COMMENT '定制工艺参数（JSON格式）',
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工序说明',
  `work_instruction` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工序备注：独立工序自身或复合父工序整体',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `group_id` bigint DEFAULT NULL COMMENT '组合ID（同一组合的工序共享此ID，NULL表示独立工序）',
  `group_order` int DEFAULT NULL COMMENT '组合顺序（第几组）',
  `parent_id` bigint DEFAULT NULL,
  `group_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '组合名称',
  `process_category` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MAIN' COMMENT '工序类别: PREPARATION准备/MAIN主要/FINISHING后处理/QUALITY质量',
  `workflow_seq` int NOT NULL DEFAULT '1' COMMENT '组（workflow）序号：同组内 process_order 从 1 递增；按路线内出现顺序 1..N',
  `index_number` int DEFAULT NULL COMMENT '下标数字（带下标工序的下标值，如4=④）',
  `precondition` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '前置依赖标识（如 PANEL_4=面板④）',
  `precondition_display` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '前置依赖显示名（如：面板④ 面板冲型）',
  `is_optional` tinyint(1) NOT NULL DEFAULT '0' COMMENT '可选工序：0-必做,1-可选',
  `is_final_process` tinyint NOT NULL DEFAULT '0' COMMENT '是否末道(成品)工序（覆盖主数据）',
  PRIMARY KEY (`detail_id`),
  UNIQUE KEY `uk_routing_workflow_process` (`routing_id`,`workflow_seq`,`process_order`),
  KEY `idx_routing_id` (`routing_id`),
  KEY `idx_process_id` (`process_id`),
  KEY `idx_process_order` (`process_order`),
  KEY `idx_detail_routing_order` (`routing_id`,`process_order`),
  KEY `idx_group_id` (`group_id`),
  KEY `idx_routing_item_parent` (`parent_id`),
  CONSTRAINT `fk_routing_detail_process` FOREIGN KEY (`process_id`) REFERENCES `engineering_standard_process` (`process_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
