--
-- Table structure for table `inventory_outbound_item`
--

DROP TABLE IF EXISTS `inventory_outbound_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inventory_outbound_item` (
  `item_id` bigint NOT NULL AUTO_INCREMENT COMMENT '明细ID',
  `outbound_id` bigint NOT NULL COMMENT '出库单ID',
  `delivery_item_id` bigint DEFAULT NULL COMMENT '来源发货明细ID，追溯sales_delivery_item.item_id',
  `inventory_item_id` bigint DEFAULT NULL COMMENT '统一库存物品ID',
  `material_id` bigint DEFAULT NULL COMMENT '材料来源ID（产品出库为NULL）',
  `material_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '物料编码（冗余）',
  `material_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '物料名称（冗余）',
  `specification` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '规格型号',
  `unit` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'PCS' COMMENT '单位',
  `quantity` decimal(12,4) NOT NULL COMMENT '出库数量',
  `unit_price` decimal(12,4) DEFAULT NULL COMMENT '出库单价',
  `amount` decimal(12,2) DEFAULT NULL COMMENT '金额',
  `batch_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '批次号',
  `location_id` bigint DEFAULT NULL COMMENT '出库库位',
  `sort_order` int DEFAULT '0' COMMENT '排序',
  `source_bom_item_id` bigint DEFAULT NULL COMMENT '对应的BOM明细ID',
  `coverage_quantity` decimal(18,4) DEFAULT NULL COMMENT '本次领料抵扣原BOM需求量',
  `substitute_of_material_id` bigint DEFAULT NULL COMMENT '被替代的BOM物料ID',
  `allocation_ratio` decimal(18,6) DEFAULT NULL COMMENT '本次替代换算系数快照',
  `allocation_loss_rate` decimal(8,4) DEFAULT NULL COMMENT '本次替代损耗率快照',
  `allocation_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '本次替代依据',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `create_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`item_id`),
  KEY `idx_outbound_id` (`outbound_id`),
  KEY `idx_material_id` (`material_id`),
  KEY `idx_batch_no` (`batch_no`),
  KEY `idx_outbound_inventory_item` (`inventory_item_id`),
  KEY `idx_outbound_delivery_item` (`delivery_item_id`),
  KEY `idx_outbound_item_source_bom` (`source_bom_item_id`),
  CONSTRAINT `fk_outbound_item_inventory_item` FOREIGN KEY (`inventory_item_id`) REFERENCES `inventory_item` (`inventory_item_id`),
  CONSTRAINT `fk_outbound_item_order` FOREIGN KEY (`outbound_id`) REFERENCES `inventory_outbound_order` (`outbound_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='出库单明细表';
