  `work_start_time` datetime DEFAULT NULL COMMENT '本次生产开始时间(可空)',
  `work_end_time` datetime DEFAULT NULL COMMENT '本次生产结束时间(可空；P2-C 校验 end>=start)',
  `report_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '报工正式提交时间(Service 显式设置)',
  `defect_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '不良原因(P2 V1 单字段，P3 再做缺陷明细)',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注(提交后不可变)',
