  `review_time` datetime DEFAULT NULL COMMENT '审批时间',
  `review_remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批备注（驳回必填）',
  `cancelled_by` bigint DEFAULT NULL COMMENT '撤销人ID',
  `cancelled_by_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '撤销人姓名',
  `cancelled_at` datetime DEFAULT NULL COMMENT '撤销时间',
  `cancel_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '撤销原因(P2-C 必填)',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`report_id`),
  UNIQUE KEY `uk_work_report_no` (`report_no`),
  KEY `idx_execution` (`execution_id`),
  KEY `idx_execution_status` (`execution_id`,`report_status`),
  KEY `idx_reporter_status` (`reporter_id`,`report_status`),
  KEY `idx_report_time` (`report_time`),
  KEY `idx_task_node` (`task_id`),
  CONSTRAINT `fk_work_report_task` FOREIGN KEY (`task_id`) REFERENCES `production_task` (`task_id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='生产报工(一次不可覆盖的生产数量/工时事实)';
