--
-- Table structure for table `review_flow`
--

DROP TABLE IF EXISTS `review_flow`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `review_flow` (
  `flow_id` bigint NOT NULL AUTO_INCREMENT COMMENT '流水ID',
  `biz_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务类型：sales_order/sales_quotation/purchase_order/engineering_bom/engineering_film/production_work_report 等',
  `biz_id` bigint NOT NULL COMMENT '业务单据ID',
  `round_no` int NOT NULL DEFAULT '1' COMMENT '审核轮次：提交(SUBMIT)时推进；驳回重提 = max(round_no)+1',
  `action_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '动作：SUBMIT/APPROVE/REJECT/SEND/CONFIRM/CANCEL/RETURN 等',
  `action_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '动作名称（展示）',
  `from_status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '动作前状态（数值/枚举原样存）',
  `to_status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '动作后状态（数值/枚举原样存）',
  `operator_id` bigint DEFAULT NULL COMMENT '操作人ID',
  `operator_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作人姓名快照',
  `comment` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '意见/驳回原因/备注（驳回必填由业务层校验）',
  `attachment_ids` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '本轮审核附件 sys_attachment.id 列表（逗号分隔；每轮独立快照）',
