/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sales_sample_transfer` (
  `transfer_id` bigint NOT NULL AUTO_INCREMENT COMMENT '转移记录ID',
  `order_id` bigint NOT NULL COMMENT '样品单ID',
  `order_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '样品单号',
  `transfer_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '转移单号',
  `product_id` bigint DEFAULT NULL COMMENT '建档产品ID',
  `bom_id` bigint DEFAULT NULL COMMENT '建档BOM ID',
  `routing_id` bigint DEFAULT NULL COMMENT '建档路线ID',
  `product_action` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'NONE' COMMENT '产品建档动作: NONE/CREATE/UPDATE',
  `bom_action` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'NONE' COMMENT 'BOM动作: NONE/CREATE/SKIP_NO_PROCESS',
  `routing_action` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'NONE' COMMENT '路线动作: NONE/CREATE/SKIP_NO_PROCESS',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'SUCCESS' COMMENT '转移结果: SUCCESS/PARTIAL/FAILED',
  `detail` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '转移明细说明',
  `create_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`transfer_id`),
  KEY `idx_transfer_order` (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='样品单产品资料转移记录';
/*!40101 SET character_set_client = @saved_cs_client */;

